"""Reusable conversions for Meridian CRM legacy storage conventions."""

from datetime import date
from decimal import Context, Decimal, ROUND_HALF_UP, localcontext


def to_iso(yyyymmdd: str | None) -> str | None:
    """Convert a legacy YYYYMMDD date to ISO format."""
    if yyyymmdd is None or yyyymmdd in ("", "00000000"):
        return None
    if len(yyyymmdd) != 8 or not yyyymmdd.isdigit():
        raise ValueError(f"invalid legacy date: {yyyymmdd!r}")

    parsed = date(
        int(yyyymmdd[0:4]),
        int(yyyymmdd[4:6]),
        int(yyyymmdd[6:8]),
    )
    return parsed.isoformat()


def from_iso(iso: str | None) -> str:
    """Convert an ISO date to legacy YYYYMMDD format."""
    if iso is None or iso == "":
        return "00000000"
    if len(iso) != 10 or iso[4] != "-" or iso[7] != "-":
        raise ValueError(f"invalid ISO date: {iso!r}")

    parsed = date.fromisoformat(iso)
    return parsed.strftime("%Y%m%d")


def yn(char: str | None) -> bool:
    """Convert the legacy Y/N convention to bool."""
    return char == "Y"


def to_minor_units(amount, currency: str | None) -> int:
    """Convert a legacy decimal amount to currency minor units."""
    if amount is None or (isinstance(amount, str) and amount.strip() == ""):
        return 0

    currency_code = "USD" if currency is None or currency.strip() == "" else currency
    exponent = 0 if currency_code.upper() == "JPY" else 2

    value = Decimal(str(amount))
    context = Context(
        prec=64,
        rounding=ROUND_HALF_UP,
        Emin=-999999999,
        Emax=999999999,
    )
    with localcontext(context):
        minor_value = value * (Decimal(10) ** exponent)
        return int(minor_value.quantize(Decimal("1"), rounding=ROUND_HALF_UP))
